def _si(key, size=20, extra=""):
    """Return inline SVG icon. key=icon name or emoji."""
    k = _EMOJI_TO_ICON.get(key, key)
    svg = _LCG_ICONS.get(k, _LCG_ICONS.get("question", ""))
    st = f"width:{size}px;height:{size}px;display:inline-block;vertical-align:middle;flex-shrink:0;{extra}"
    return svg.replace("<svg ", f'<svg style="{st}" ', 1)


