CITY_FACTS = {
    # Format: city_state -> (humidity_note, seasonal_note, local_tip)
    "New York_NY": ("high humidity", "winters harsh, summers humid", "NYC contractors are licensed by NYC DOB — verify at nyc.gov/buildings"),
    "Los Angeles_CA": ("dry climate", "mild year-round", "California requires CSLB licence — verify at cslb.ca.gov"),
    "Chicago_IL": ("continental climate", "harsh winters, hot summers", "Illinois contractors need IDFPR licence"),
    "Houston_TX": ("high humidity 70%+ year-round", "hot summers, mild winters", "Texas requires TDLR licence for most trades"),
    "Phoenix_AZ": ("desert dry", "107+ days above 100°F", "Verify contractor at azroc.gov"),
    "Miami_FL": ("80% humidity year-round", "hurricane season Jun-Nov", "Florida requires state licence — verify at myfloridalicense.com"),
    "Seattle_WA": ("frequent rain", "mild but wet", "Washington requires L&I contractor registration"),
    "Denver_CO": ("semi-arid, 300 sunny days", "cold winters, hail season Apr-Jun", "Colorado requires DORA licence"),
    "Dallas_TX": ("hot humid summers", "tornado season Mar-Jun", "Texas requires TDLR licence for most trades"),
    "Atlanta_GA": ("humid subtropical", "hot summers, mild winters", "Georgia requires state contractor licence"),
}

def get_city_facts(city, state):
    key = f"{city}_{state}"
    return CITY_FACTS.get(key, (
        "varies by season",
        "seasonal factors affect pricing",
        f"Always verify contractor licences with your state licensing board"
    ))

