SITE_ROUNDING = {
    "fixitcosts":      50,
    "lawyercostguide": 50,
    "vetbillguide":    1,
    "carfixcosts":     1,
    "salarycityguide": 500,
}

# Per-service rounding overrides (slug → rnd) — takes priority over site-level
SERVICE_ROUNDING_OVERRIDE = {
    "window-replacement": 10,
}



def build_price_trio(svc_slug, lo, avg, hi, a, fmt_fn):
    """Render the three price cards in the hero.
    v31: PI gets case-value labels + $0 Out of Pocket badge.
    v34: Real prices rendered in HTML as initial text — JS overwrites with animation.
         Crawlers, no-JS environments, and slow connections all see real numbers instantly.
         $0 initial display is now only visible for a single frame before countUp fires.
    ONLY personal-injury is branched — no other service is affected.
    """
    if svc_slug == "personal-injury":
        lo_label  = "Small Claim"
        lo_sub    = "Soft tissue / clear liability"
        avg_label = "Standard Claim"
        avg_sub   = "Moderate injury / disputed liability"
        hi_label  = "Major Claim"
        hi_sub    = "Catastrophic injury / trial"
        badge     = "Case Value Est."
        zero_pill = f'<div style="display:inline-flex;align-items:center;gap:.3rem;background:rgba(34,197,94,.15);border:1px solid rgba(34,197,94,.4);border-radius:100px;padding:.2rem .6rem;margin-top:.35rem;font-size:.6rem;font-weight:800;color:#4ade80;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;">✓ $0 Out of Pocket</div>'
    else:
        lo_label  = "Budget"
        lo_sub    = "Basic / entry level"
        avg_label = "Most Common"
        avg_sub   = "Standard quality"
        hi_label  = "Premium"
        hi_sub    = "High-end / complex"
        badge     = "Average"
        zero_pill = ""

    # v34: pre-render real prices as initial text content
    # JS countUp overwrites these with the animation — but crawlers/no-JS see real values
    lo_fmt  = fmt_fn(lo)
    avg_fmt = fmt_fn(avg)
    hi_fmt  = fmt_fn(hi)

    return f"""<div class="price-trio">
    <div class="ptc"><div><div class="ptc-label">{lo_label}</div><div class="ptc-val" data-val="{lo}">{lo_fmt}</div><div class="ptc-sub">{lo_sub}</div></div></div>
    <div class="ptc ptc-avg"><div><div class="ptc-label">{avg_label}</div><div class="ptc-val" data-val="{avg}">{avg_fmt}</div><div class="ptc-sub">{avg_sub}</div>{zero_pill}</div><span class="ptc-badge">{badge}</span></div>
    <div class="ptc"><div><div class="ptc-label">{hi_label}</div><div class="ptc-val" data-val="{hi}">{hi_fmt}</div><div class="ptc-sub">{hi_sub}</div></div></div>
  </div>"""


def build_price_spectrum(lo, avg, hi, nat_avg, a, a2, city, fmt_fn):
    """SVG-free pure-CSS price spectrum bar showing city vs national average.
    v30: positions now range-relative — dot and tick placed within lo→hi track,
    not against an arbitrary scale_max. This fixes visually wrong positions on
    high-COL pages where the range was compressed to the bottom of the old scale.
    """
    # Range span for positioning — everything is relative to lo→hi
    span = hi - lo if hi > lo else 1

    # Clamp within 2–98% so dot/tick never sits flush at the edge
    def to_pct(val):
        return min(max((val - lo) / span * 100, 2), 98)

    avg_pct  = to_pct(avg)
    nat_pct  = to_pct(nat_avg)
    # Fill always runs full width of the track (lo to hi = 0% to 100%)
    # so left=0 and width=100 — the track itself IS the range
    fill_w   = 100.0
    lo_pct   = 0.0

    city_label = fmt_fn(avg)
    nat_label  = fmt_fn(nat_avg)
    direction  = "above" if avg > nat_avg else "below" if avg < nat_avg else "at"
    diff_pct   = abs(round((avg - nat_avg) / nat_avg * 100))
    if direction == "above":
        compare = f"{diff_pct}% above national avg"
        compare_color = "#f87171"
    elif direction == "below":
        compare = f"{diff_pct}% below national avg"
        compare_color = "#34d399"
    else:
        compare = "at national avg"
        compare_color = "rgba(255,255,255,.5)"
    return f"""<div class="psb-wrap rv">
  <div class="psb-title">Price Spectrum &mdash; {city} vs National Average</div>
  <div class="psb-track">
    <div class="psb-fill" style="left:{lo_pct:.1f}%;width:{fill_w:.1f}%"></div>
    <div class="psb-city-dot" style="left:{avg_pct:.1f}%"></div>
    <div class="psb-nat-tick" style="left:{nat_pct:.1f}%"></div>
  </div>
  <div class="psb-labels"><span>{fmt_fn(lo)}</span><span>{fmt_fn(hi)}</span></div>
  <div class="psb-legend">
    <div class="psb-leg-item"><div class="psb-leg-dot" style="background:{a2}"></div>{city}: <strong style="color:#fff;margin-left:.2rem">{city_label}</strong></div>
    <div class="psb-leg-item"><div class="psb-leg-dot" style="background:rgba(255,255,255,.4)"></div>National avg: <strong style="color:rgba(255,255,255,.6);margin-left:.2rem">{nat_label}</strong></div>
    <div class="psb-leg-item" style="color:{compare_color}"><strong>{compare}</strong></div>
  </div>
</div>"""


