    # COL comparison text
    nat_avg = service['base_avg']
    nat_avg_fmt = f"${nat_avg:,.0f}"
    city_avg_fmt = f"${avg:,.0f}"
    svc_short = service['name'].replace(' Lawyer','').replace(' Attorney','').replace(' Costs','')

