def build_places_api():
    """Vercel serverless function — proxies Google Places API call.
    Key stored in Vercel env vars (GOOGLE_PLACES_KEY), never in HTML.
    Deploy: Vercel Dashboard → lawyercostguide → Settings → Environment Variables
    Add: GOOGLE_PLACES_KEY = AIzaSyBoboxzKeh94t5YRMnkyeGFhoVNbLtD8vM
    """
    return """export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }
  const apiKey = process.env.GOOGLE_PLACES_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: 'Places API key not configured' });
  }
  const { query } = req.body;
  if (!query) {
    return res.status(400).json({ error: 'Missing query' });
  }
  try {
    const response = await fetch('https://places.googleapis.com/v1/places:searchText', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Goog-Api-Key': apiKey,
        'X-Goog-FieldMask': 'places.displayName,places.formattedAddress,places.rating,places.userRatingCount,places.websiteUri,places.nationalPhoneNumber,places.id,places.regularOpeningHours,places.location'
      },
      body: JSON.stringify({
        textQuery: query,
        maxResultCount: 10,
        languageCode: 'en'
      })
    });
    const data = await response.json();
    res.status(response.status).json(data);
  } catch (err) {
    res.status(500).json({ error: 'Places service unavailable' });
  }
}
"""


def build_match_api():
    """Vercel serverless function — proxies Anthropic API call.
    Key stored in Vercel env vars (ANTHROPIC_API_KEY), never in HTML.
    Deploy: Vercel Dashboard → lawyercostguide → Settings → Environment Variables
    """
    return """export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: 'API key not configured' });
  }
  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify(req.body)
    });
    const data = await response.json();
    res.status(response.status).json(data);
  } catch (err) {
    res.status(500).json({ error: 'Match service unavailable' });
  }
}
"""


def build_vercel_config():
    return json.dumps({
        "cleanUrls": True,
        "trailingSlash": False,
        "rewrites": [
            {"source": "/methodology", "destination": "/methodology.html"},
            {"source": "/about", "destination": "/about.html"},
            {"source": "/privacy", "destination": "/privacy.html"},
            {"source": "/terms", "destination": "/terms.html"},
            {"source": "/llms.txt", "destination": "/llms.txt"},
            {"source": "/ads.txt", "destination": "/ads.txt"},
            {"source": "/yandex_c122958a60c2b113.html", "destination": "/yandex_c122958a60c2b113.html"},
            {"source": "/yandex_a766f36031fd5af6.html", "destination": "/yandex_a766f36031fd5af6.html"},
        ],
        "headers": [
            {"source": "/ads.txt", "headers": [
                {"key": "Content-Type", "value": "text/plain"},
                {"key": "Cache-Control", "value": "public, max-age=86400"},
            ]},
            {"source": "/(.*\.html)", "headers": [
                {"key": "X-Content-Type-Options", "value": "nosniff"},
                {"key": "X-Frame-Options", "value": "DENY"},
                {"key": "Cache-Control", "value": "public, max-age=0, must-revalidate"},
            ]},
            {"source": "/(.*)", "headers": [
                {"key": "X-Content-Type-Options", "value": "nosniff"},
                {"key": "X-Frame-Options", "value": "DENY"},
                {"key": "Cache-Control", "value": "public, max-age=86400, stale-while-revalidate=604800"},
            ]}
        ]
    }, indent=2)

