def generate_all():
    output_root = Path("./output")
    cities = LAUNCH_CITIES

    # ── Pre-flight: validate city data before generating any pages ──
    print("\n🔍 Pre-flight city data validation...")
    validate_city_data()

    total_pages = 0
    for site_key, s in SITES.items():
        print(f"\n{'='*60}")
        print(f"Generating {s['name']} ({s['domain']})")
        print(f"{'='*60}")

        site_dir = output_root / site_key
        site_dir.mkdir(parents=True, exist_ok=True)

        # Homepage
        (site_dir / "index.html").write_text(build_homepage(site_key, s), encoding="utf-8")
        print(f"  ✅ Homepage")

        # Support pages
        for page in ["about", "methodology", "privacy", "terms"]:
            (site_dir / f"{page}.html").write_text(build_support_page(page, s), encoding="utf-8")
        print(f"  ✅ Support pages (about, methodology, privacy, terms)")

        # Insights pages (LCG + FixItCosts)
        if site_key in ("lawyercostguide", "fixitcosts"):
            ins_dir = site_dir / "insights"
            ins_dir.mkdir(exist_ok=True)
            (ins_dir / "index.html").write_text(build_insights_hub(s, site_key), encoding="utf-8")
            art_list = FIC_ARTICLES if site_key == "fixitcosts" else ARTICLES
            for art in art_list:
                (ins_dir / f"{art['slug']}.html").write_text(build_article_page(art, s, site_key), encoding="utf-8")
            print(f"  ✅ Insights hub + {len(art_list)} articles")

        # v44: Attorney Directory pages — LCG only
        # /find-attorney/{svc_slug}/{city_slug}-{state_lower}
        if site_key == "lawyercostguide":
            dir_base = site_dir / "find-attorney"
            dir_base.mkdir(exist_ok=True)
            dir_page_count = 0
            for svc in SERVICES["lawyercostguide"]:
                svc_dir_d = dir_base / svc["slug"]
                svc_dir_d.mkdir(exist_ok=True)
                for city_tuple in cities:
                    city        = city_tuple[0]
                    state       = city_tuple[1]
                    col         = city_tuple[2]
                    city_slug   = city.lower().replace(" ", "-").replace(".", "").replace(",", "").replace("'", "").replace("/", "-")
                    state_lower = state.lower()
                    avg         = int(svc["base_avg"] * col / 100)
                    lo          = int(svc["base_lo"]  * col / 100)
                    hi          = int(svc["base_hi"]  * col / 100)
                    fname       = f"{city_slug}-{state_lower}.html"
                    html        = build_directory_page(site_key, s, svc, city, state, city_slug, state_lower, avg, lo, hi)
                    (svc_dir_d / fname).write_text(html, encoding="utf-8")
                    dir_page_count += 1
            print(f"  ✅ Attorney directory: {dir_page_count} pages (12 practices × 161 cities)")

        # Sitemap + robots + vercel + favicon
        (site_dir / "sitemap.xml").write_text(build_sitemap(site_key, s, cities), encoding="utf-8")
        (site_dir / "robots.txt").write_text(build_robots(s), encoding="utf-8")
        (site_dir / "vercel.json").write_text(build_vercel_config(), encoding="utf-8")
        fav_data = build_favicon(site_key)
        if isinstance(fav_data, bytes):
            (site_dir / "favicon.png").write_bytes(fav_data)
            # Also write nav logo at 32px
            import base64
            (site_dir / "logo.png").write_bytes(base64.b64decode(LCG_LOGO_NAV_1X_B64))
            (site_dir / "logo@2x.png").write_bytes(base64.b64decode(LCG_LOGO_NAV_2X_B64))
            (site_dir / "logo@3x.png").write_bytes(base64.b64decode(LCG_LOGO_NAV_3X_B64))
        else:
            (site_dir / "favicon.svg").write_text(fav_data, encoding="utf-8")
        print(f"  ✅ sitemap.xml, robots.txt, vercel.json, favicon.svg")

        # Inner pages + hub pages
        services = SERVICES[site_key]
        # llms.txt written here — after services is defined
        (site_dir / "llms.txt").write_text(build_llms_txt(site_key, s, services, cities), encoding="utf-8")
        print(f"  ✅ llms.txt")
        # ads.txt — required for AdSense to serve ads
        (site_dir / "ads.txt").write_text(f"google.com, {ADSENSE_PUB}, DIRECT, f08c47fec0942fa0\n", encoding="utf-8")
        print(f"  ✅ ads.txt")

        # v46c-AI: Serverless proxies for Anthropic + Places — LCG only
        if site_key == "lawyercostguide":
            api_dir = site_dir / "api"
            api_dir.mkdir(exist_ok=True)
            (api_dir / "match.js").write_text(build_match_api(), encoding="utf-8")
            (api_dir / "places.js").write_text(build_places_api(), encoding="utf-8")
            print(f"  ✅ api/match.js + api/places.js (add ANTHROPIC_API_KEY + GOOGLE_PLACES_KEY to Vercel env vars)")
        YANDEX_TOKENS = {
            "lawyercostguide": ("yandex_c122958a60c2b113.html", "c122958a60c2b113"),
            "fixitcosts":      ("yandex_a766f36031fd5af6.html", "a766f36031fd5af6"),
        }
        if site_key in YANDEX_TOKENS:
            fname, token = YANDEX_TOKENS[site_key]
            yandex_html = f"""<html>
    <head>
        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8">
    </head>
    <body>Verification: {token}</body>
</html>"""
            (site_dir / fname).write_text(yandex_html, encoding="utf-8")
            print(f"  ✅ {fname}")
        page_count = 0
        for svc in services:
            svc_dir = site_dir / svc["slug"]
            svc_dir.mkdir(exist_ok=True)
            # Hub page — service index listing all cities
            (svc_dir / "index.html").write_text(build_practice_hub(site_key, s, svc, cities), encoding="utf-8")
            for city, state, col in cities:
                city_slug = city.lower().replace(" ","-").replace(".","-")
                fname = f"{city_slug}-{state.lower()}.html"
                page_html = build_inner_page(site_key, s, svc, city, state, col)
                (svc_dir / fname).write_text(page_html, encoding="utf-8")
                page_count += 1
                if page_count % 100 == 0:
                    print(f"  ... {page_count} inner pages generated")

        total_pages += page_count
        print(f"  ✅ {page_count} inner pages ({len(services)} services × {len(cities)} cities)")
        print(f"  📁 Output: ./output/{site_key}/")

    print(f"\n{'='*60}")
    print(f"✅ GENERATION COMPLETE")
    # ── VALIDATION REPORT ──────────────────────────────────────────
    if _VALIDATION_ISSUES:
        print(f"\n⚠️  VALIDATION REPORT — {len(_VALIDATION_ISSUES)} issue(s) found:")
        # Group by type — v29: added COLOUR_BLEED, LAW_COPY_BLEED, WIZARD_PLAIN_BUTTONS
        # v30: added RETAINER_COPY_WRONG, PSB_TICK_WRONG, PSB_DOT_WRONG, DUPLICATE_STEP_DOTS,
        #      CITY_CONTAMINATED_FACTS, PER_UNIT_PRICE_LEAK, CLIMATE_TRUNCATED, CLIMATE_FRAGMENT
        # v30b: added NATIONAL_RATE_LEAK, IMMIGRATION_TIP_WRONG
        # v37: added FIC_LEGAL_FUNNEL_BLEED, FIC_WIZARD_CTA_BLEED
        errors   = [i for i in _VALIDATION_ISSUES if any(x in i for x in [
            "FEE_TYPE", "CONTINGENCY_CAP", "WRONG_CONTENT",
            "COLOUR_BLEED", "LAW_COPY_BLEED",
            "RETAINER_COPY_WRONG", "CITY_CONTAMINATED_FACTS", "PER_UNIT_PRICE_LEAK",
            "NATIONAL_RATE_LEAK", "IMMIGRATION_TIP_WRONG",
            "FIC_LEGAL_FUNNEL_BLEED", "FIC_WIZARD_CTA_BLEED",
        ])]
        warnings = [i for i in _VALIDATION_ISSUES if i not in errors]
        if errors:
            print(f"\n  🔴 ERRORS ({len(errors)}) — fix before deploying:")
            for e in errors[:20]: print(e)
        if warnings:
            print(f"\n  🟡 WARNINGS ({len(warnings)}) — review before deploying:")
            for w in warnings[:20]: print(w)
        if len(_VALIDATION_ISSUES) > 40:
            print(f"  ... and {len(_VALIDATION_ISSUES)-40} more. Fix systemic issues first.")
    else:
        print("✅ VALIDATION CLEAN — no contradictions found")
    print(f"   Total pages: {total_pages + (len(SITES)*6):,}")
    print(f"   Sites: {len(SITES)}")
    print(f"   Output: ./output/")
    print(f"\nNext steps:")
    print(f"   1. cd output/<site-name>")
    print(f"   2. git init && git remote add origin <your-github-repo-url>")
    print(f"   3. git add . && git commit -m 'Initial launch' && git push")
    print(f"   4. Vercel auto-deploys on push")
    print(f"{'='*60}\n")

