def build_city_market_section(site_key, service, city, state, col, avg, lo, hi, vs_nat, local_tip):
    """Single merged market section replacing both city_intro and city_legal_section for lawyercostguide"""
    if site_key != "lawyercostguide":
        return ""

    data = CITY_LEGAL_DATA.get(city)
    svc_name = service["name"]
    svc_slug = service["slug"]

    if not data:
        # State-aware fallback for non-priority cities
        # Uses STATE_BAR, STATE_WAITING, STATE_FILING, STATE_COMMUNITY_PROPERTY
        bar_url_fb, bar_name_fb = STATE_BAR.get(state, ("americanbar.org", "American Bar Association"))
        col_desc = f"{col-100}% above" if col > 100 else f"{100-col}% below" if col < 100 else "at"
        filing_fb = STATE_FILING.get(state, "varies by county")
        waiting_fb = STATE_WAITING.get(state, "check your state's specific requirement")
        cp_note = f"{state} is a community property state — assets acquired during marriage split 50/50 by default." if state in STATE_COMMUNITY_PROPERTY else f"{state} is an equitable distribution state — courts divide assets fairly, not necessarily equally."

        # Practice-area specific content for fallback cities
        if svc_slug == "divorce-lawyer":
            pt_div = get_practice_truth("divorce-lawyer")
            hourly_lo_div = int(pt_div.get("hourly_lo", 200) * col / 100)
            hourly_hi_div = int(pt_div.get("hourly_hi", 650) * col / 100)
            bullets_html = "".join(f'<li><span class="cmb-label">{l}</span> {t}</li>' for l, t in [
                ("Court", f"File at your county courthouse — {state} divorce is a state court matter"),
                ("Filing fee", f"<strong>{filing_fb}</strong> to file the petition"),
                ("Waiting period", waiting_fb),
                ("Property law", cp_note),
                ("Rates", f"<strong>{fmt(hourly_lo_div)}–{fmt(hourly_hi_div)}/hr</strong> typical · COL index {col} ({col_desc} national)"),
                ("Verify", f"<a href='https://{bar_url_fb}' target='_blank'>{bar_url_fb}</a> ({bar_name_fb}) — verify licence and disciplinary history"),
            ])
        elif svc_slug in ("criminal-defense", "dui-attorney"):
            pt_cr = get_practice_truth(svc_slug)
            hourly_lo_cr = int(pt_cr.get("hourly_lo", 200) * col / 100)
            hourly_hi_cr = int(pt_cr.get("hourly_hi", 500) * col / 100)
            dui_note = "DMV licence deadline is separate from the criminal case — contact an attorney immediately after arrest to protect both" if svc_slug == "dui-attorney" else "Always retain counsel before speaking with law enforcement — statements made without counsel present cannot be taken back"
            bullets_html = "".join(f'<li><span class="cmb-label">{l}</span> {t}</li>' for l, t in [
                ("Court", f"State criminal cases are heard in {state} county-level courts — confirm your assigned courthouse after arraignment"),
                ("Rates", f"<strong>{fmt(hourly_lo_cr)}–{fmt(hourly_hi_cr)}/hr</strong> typical · COL index {col} ({col_desc} national) · flat fee most common for criminal/DUI"),
                ("Fee type", "Flat fee is standard — most criminal/DUI attorneys quote all-in before taking the case"),
                ("Tip", dui_note),
                ("Verify", f"<a href='https://{bar_url_fb}' target='_blank'>{bar_url_fb}</a> ({bar_name_fb}) before retaining anyone"),
            ])
        elif svc_slug == "bankruptcy-attorney":
            pt = get_practice_truth(svc_slug)
            ch7_lo_adj = int(pt.get("ch7_lo", 1000) * col / 100)
            ch7_hi_adj = int(pt.get("ch7_hi", 2200) * col / 100)
            ch13_lo_adj = int(pt.get("ch13_lo", 3000) * col / 100)
            ch13_hi_adj = int(pt.get("ch13_hi", 6000) * col / 100)
            bullets_html = "".join(f'<li><span class="cmb-label">{l}</span> {t}</li>' for l, t in [
                ("Court", f"US Bankruptcy Court — {state} district (federal, not {state} state court)"),
                ("Ch7 flat fee", f"<strong>{fmt(ch7_lo_adj)}–{fmt(ch7_hi_adj)}</strong> attorney fee + $338 filing fee"),
                ("Ch13 flat fee", f"<strong>{fmt(ch13_lo_adj)}–{fmt(ch13_hi_adj)}</strong> attorney fee + $313 filing fee"),
                ("Exemptions", f"{state}'s exemption laws determine which assets you keep — ask your attorney specifically about {state} exemptions"),
                ("Verify", f"<a href='https://{bar_url_fb}' target='_blank'>{bar_url_fb}</a> ({bar_name_fb}) before retaining anyone"),
            ])
        elif svc_slug == "personal-injury":
            # State-specific contingency cap
            ca_ny_cap_states = {"CA": "33%", "NY": "33%"}
            contingency_display = ca_ny_cap_states.get(state, "33–40%")
            cap_note = f" (capped at {ca_ny_cap_states[state]} by {state} law)" if state in ca_ny_cap_states else ""
            bullets_html = "".join(f'<li><span class="cmb-label">{l}</span> {t}</li>' for l, t in [
                ("Fee", f"<strong>Contingency only</strong> — no upfront cost · attorney takes <strong>{contingency_display}</strong> of settlement{cap_note}"),
                ("Settlement range", f"<strong>{fmt(lo)}–{fmt(hi)}</strong> typical range · avg <strong>{fmt(avg)}</strong> · COL index {col} ({col_desc} national)"),
                ("Tip", f"Never accept a direct insurance offer without consulting a {city} personal injury attorney first"),
                ("Verify", f"<a href='https://{bar_url_fb}' target='_blank'>{bar_url_fb}</a> ({bar_name_fb}) before signing anything"),
            ])
        else:
            # For all remaining practice areas: compute COL-adjusted hourly rate from PRACTICE_TRUTH
            pt_fb = get_practice_truth(svc_slug)
            hourly_lo_fb = int(pt_fb.get("hourly_lo", 200) * col / 100)
            hourly_hi_fb = int(pt_fb.get("hourly_hi", 500) * col / 100)
            fee_type_fb  = pt_fb.get("fee_type", "hourly")

            if fee_type_fb == "flat":
                # Flat-fee practices: show flat fee range, not hourly
                rates_label = "Flat fee"
                rates_val   = f"<strong>{fmt(lo)}–{fmt(hi)}</strong> typical range · most work priced per engagement"
            elif fee_type_fb == "contingency":
                rates_label = "Fee"
                ca_ny_cap = {"CA": "33%", "NY": "33%"}.get(state, "33–40%")
                rates_val  = f"<strong>Contingency only</strong> — attorney takes {ca_ny_cap} of recovery · no upfront cost"
            else:
                # Hourly practice areas: show /hr rate, not lo-hi case range
                rates_label = "Rates"
                rates_val   = f"<strong>{fmt(hourly_lo_fb)}–{fmt(hourly_hi_fb)}/hr</strong> typical · COL index {col} ({col_desc} national)"

            bullets_html = "".join(f'<li><span class="cmb-label">{l}</span> {t}</li>' for l, t in [
                (rates_label, rates_val),
                ("Local market", f"{city} {svc_name.lower()} market sits {col_desc} the national baseline (COL index {col})"),
                ("Tip", f"Always compare 3 {city} attorneys before retaining — fees vary significantly even within the same city"),
                ("Verify", f"<a href='https://{bar_url_fb}' target='_blank'>{bar_url_fb}</a> ({bar_name_fb}) before paying a retainer"),
            ])

        return f"""<div class="cmb">
      <div class="cmb-head">{_si("gavel", 18)} {city} — {svc_name} Market<span class="cmb-head-badge">2026 Data</span></div>
      <ul class="cmb-list">{bullets_html}</ul>
      <div class="cmb-footer">State data verified March 2026 · {bar_url_fb}</div>
    </div>"""

    hourly = data['hourly_range']
    retainer = data['retainer_range']
    bar_url = data['bar_url']
