        # S6 fix: PI uses contingency only — no hourly rate or retainer shown
        # S5 fix: get contingency cap from CITY_OVERRIDES or PRACTICE_TRUTH
        if svc_slug == "personal-injury":
            pt = get_practice_truth(svc_slug)
            override = get_city_override(svc_slug, city, state)
