    retainer = cd.get('retainer_range','$3,000–$8,000')
    court = cd.get('court','')
    court_url = cd.get('court_url','')
    bar = cd.get('bar_name','state bar')
    bar_url = cd.get('bar_url','state bar website')
    backlog = cd.get('backlog_note','')
    mediation = cd.get('mediation_note','')
    waiting = cd.get('waiting_period','')
    unique = cd.get('unique_fact','')
    local_tip = cd.get('local_tip','')
    cp = cd.get('community_property',False)
    _contested_raw = int(avg * 1.25)
    _contested_rounded = round(_contested_raw / 100) * 100
    avg_contested = fmt(_contested_rounded)

